  class RiskEngine { public function evaluateRisk(array $plan, array $analysis = []): array { $riskFactors = []; $score = 0; $filesToCreate = $plan['files_to_create'] ?? []; $filesToModify = $plan['files_to_modify'] ?? []; $filesToDelete = $plan['files_to_delete'] ?? []; if (count($filesToDelete) > 0) { $score += 40; $riskFactors[] = "Eliminación de " . count($filesToDelete) . " archivos en el proyecto."; } foreach (array_merge($filesToCreate, $filesToModify) as $file) { if (str_contains($file, 'Security') || str_contains($file, 'Auth') || str_contains($file, 'Token')) { $score += 35; $riskFactors[] = "Modificación de submódulos de Autenticación/Seguridad ({$file})."; } if (str_contains($file, 'migrations') || str_contains($file, '.sql') || str_contains($file, 'database')) { $score += 25; $riskFactors[] = "Alteración de esquema de Base de Datos ({$file})."; } if (str_contains($file, '.env') || str_contains($file, 'config')) { $score += 30; $riskFactors[] = "Modificación de archivos de Configuración Global ({$file})."; } } if (count($filesToModify) > 10) { $score += 20; $riskFactors[] = "Modificación masiva de archivos (" . count($filesToModify) . " archivos)."; } $level = 'LOW'; if ($score >= 70) { $level = 'CRITICAL'; } elseif ($score >= 45) { $level = 'HIGH'; } elseif ($score >= 20) { $level = 'MEDIUM'; } if (empty($riskFactors)) { $riskFactors[] = "Cambios aislados estándar sin modificaciones críticas de infraestructura."; } return [ 'level' => $level, 'score' => $score, 'factors' => $riskFactors, 'requires_human_approval' => in_array($level, ['HIGH', 'CRITICAL']) ]; } } 